insert into jom_private.questions(id,payload,core_order) values
('q1','{"id":"q1","round":0,"type":"quiz","tag":"Community + knowledge","seconds":45,"stem":"A town needs enough engineers to keep its water supply safe. Which idea fits?","options":["Every person must become an engineer","Fardu kifayah: enough people meet the shared need","Science is only a private hobby","Engineering replaces every other duty"],"correct":1,"explanation":"Fardu kifayah is a collective obligation. The community needs sufficient expertise; every individual does not need the same career.","follow":"What is another profession that meets a shared community need? Explain the need."}'::jsonb,0),
('q2','{"id":"q2","round":0,"type":"quiz","tag":"Scientific thinking","seconds":45,"stem":"A claim has 50,000 likes. What should a scientist ask next?","options":["Who shared it first?","Is the speaker famous?","What observations or tests support it?","Can we make it more popular?"],"correct":2,"explanation":"Popularity is not evidence. Scientific claims about nature should be open to observation and testing.","follow":"What evidence would change your mind? Give one concrete example."}'::jsonb,1),
('q3','{"id":"q3","round":0,"type":"quiz","tag":"Golden Age","seconds":45,"stem":"Which pair belongs on a correct revision card?","options":["Ibn Sina — Al-Qanun fi al-Tibb","Hunayn ibn Ishaq — inventor of steam factories","Al-Khwarizmi — The Canon of Medicine","Pythagoras — Arabic medical translation"],"correct":0,"explanation":"Ibn Sina is associated with Al-Qanun fi al-Tibb, The Canon of Medicine. Hunayn ibn Ishaq is associated with translation; Al-Khwarizmi with mathematics.","follow":"Name one other scholar and explain their contribution in a full sentence."}'::jsonb,2),
('q4','{"id":"q4","round":0,"type":"quiz","tag":"House of Wisdom","seconds":45,"stem":"What made checking a translation against its original valuable?","options":["It made every old claim automatically true","It removed the need for new research","It kept all knowledge inside one community","It helped preserve meaning and accuracy"],"correct":3,"explanation":"Checking a translation helps avoid errors in transmitting knowledge. It does not automatically prove every claim inside a text.","follow":"How is this similar to checking an AI-generated answer against a source?"}'::jsonb,3),
('q5','{"id":"q5","round":0,"type":"quiz","tag":"Science + ethics","seconds":45,"stem":"A device works well but harms its users. Is technical success enough?","options":["Yes, if it earns a profit","No: ethical and social responsibilities also matter","Yes, if its inventor has good intentions","No technology should ever be developed"],"correct":1,"explanation":"The Islamic framework connects scientific activity with ethical principles and social responsibility. Technical performance alone is insufficient.","follow":"Name one responsibility the developer has to users."}'::jsonb,4),
('q6','{"id":"q6","round":0,"type":"quiz","tag":"Technology through time","seconds":45,"stem":"In this course’s three-phase model, which example belongs to Phase II?","options":["Hand-crafted tools","Steam-powered factory production","Computers, networks and digital automation","Basic manual agricultural work"],"correct":2,"explanation":"Here, Phase II means the Digital Revolution and information technology. Phase I means industrial mechanization; the pre-revolutionary phase emphasizes manual tools.","follow":"Why would a steam engine fit a different phase? Use the course model."}'::jsonb,5),
('ai1','{"id":"ai1","round":1,"type":"claim","tag":"Ethical reasoning","seconds":75,"claim":"“The device will help many people. Therefore, hiding failed trials is acceptable because the goal is good.”","stem":"Which correction identifies the main problem?","options":["Hiding failures is fine when the goal is useful","A good goal removes social responsibility","Every experiment must succeed","A good goal does not justify dishonest methods"],"correct":3,"explanation":"Scientific honesty requires accurate reporting. A beneficial purpose does not make deception acceptable.","follow":"Rewrite the answer in two sentences: name the principle, then link it to the hidden failures."}'::jsonb,6),
('ai2','{"id":"ai2","round":1,"type":"claim","tag":"Scholar mix-up","seconds":75,"claim":"“Ibn Sina is best associated with algebra, while Al-Khwarizmi wrote The Canon of Medicine.”","stem":"Which repair makes the two associations accurate?","options":["Al-Khwarizmi → algebra; Ibn Sina → medicine","Both scholars → steam engines","Keep both associations as written","Hunayn → The Canon; Pythagoras → algebra"],"correct":0,"explanation":"The two associations have been swapped. Al-Khwarizmi is linked with mathematics and algebra; Ibn Sina authored The Canon of Medicine.","follow":"If the answer sounds confident, what should you check before sharing it?"}'::jsonb,7),
('ai3','{"id":"ai3","round":1,"type":"claim","tag":"Fardu kifayah","seconds":75,"claim":"“Fardu kifayah means every Muslim must personally become a scientist. Otherwise, the duty is never fulfilled.”","stem":"Which phrase needs to replace “every Muslim must personally become a scientist”?","options":["No one needs scientific expertise","Only wealthy people should learn science","Enough members meet the community’s need","Every profession is a private hobby"],"correct":2,"explanation":"Fardu kifayah concerns a collective need fulfilled by sufficient members of a community. It does not assign the same profession to everyone.","follow":"Give an example outside medicine or engineering, and explain the community need."}'::jsonb,8),
('ai4','{"id":"ai4","round":1,"type":"claim","tag":"Course model","seconds":75,"claim":"“Technology Revolution Phase I is the internet era. Phase II is the introduction of steam-powered factories.”","stem":"Using our course model, what is the best correction?","options":["Both phases refer only to hand tools","Phase I → industrial; Phase II → digital","Phase I → digital; Phase II → manual","There is no distinction between the phases"],"correct":1,"explanation":"In this course model, Phase I is industrial mechanization and Phase II is digital information technology. Other historical models can use different numbering.","follow":"Explain one change in how people work between these two phases."}'::jsonb,9),
('A1','{"id":"A1","stem":"A community trains enough engineers to maintain a safe water supply. Which obligation does this best illustrate?","options":["Fardu kifayah","A duty limited to religious teachers","A personal hobby","Fardu ain"],"correct":0,"explanation":"Fardu kifayah is a collective obligation fulfilled by sufficient members serving a community need.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A2','{"id":"A2","stem":"A village wants to reduce ignorance among its young people. Which action most directly supports this aim?","options":["Discourage questions","Provide accessible education","Replace learning with entertainment","Limit access to books"],"correct":1,"explanation":"Education develops knowledge and helps people move beyond ignorance.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A3','{"id":"A3","stem":"The Latin root scientia helps explain science as a form of what?","options":["Handicraft","Political authority","Knowledge","Religious ceremony"],"correct":2,"explanation":"Scientia is the Latin word associated with knowledge.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A4','{"id":"A4","stem":"Which claim is suitable for a scientific investigation?","options":["A claim protected from every possible test","A claim that can be checked using observations","A claim supported only by a famous person","A claim accepted only because it is popular"],"correct":1,"explanation":"Scientific claims about nature should be open to evidence and testing.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A5','{"id":"A5","stem":"A student links the Greek term techne to making a tool by hand. Which meaning is closest?","options":["A moral command","Art or craft","A scientific law","A written argument"],"correct":1,"explanation":"Techne refers to art, craft or skilled handiwork.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A6','{"id":"A6","stem":"Which set contains only intellectual activities identified in scientific methodology?","options":["Observation, hypothesis, description, generalization","Observation, advertising, description, imitation","Description, guessing, sales, repetition","Hypothesis, popularity, secrecy, generalization"],"correct":0,"explanation":"The course lists observation, hypotheses, descriptions and generalizations as intellectual activities.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A7','{"id":"A7","stem":"In the course account of Islamic methodology, which belongs to the non-empirical category?","options":["Measuring temperature","Inspiration and kashf","Recording observations","Performing a controlled experiment"],"correct":1,"explanation":"Inspiration and kashf are classified as non-empirical in this course account, rather than as measurements.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A8','{"id":"A8","stem":"A student says, \"Learning engineering can have no religious value because it is worldly knowledge.\" What is the best correction?","options":["Every Muslim must become an engineer","Engineering replaces religious duties","Only religious teachers may learn engineering","Beneficial scientific learning can carry religious responsibility"],"correct":3,"explanation":"The course rejects treating beneficial scientific knowledge as entirely separate from religious responsibility.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A9','{"id":"A9","stem":"Which trio matches the three philosophy-of-technology approaches listed in the course?","options":["Ontological, commercial, political","Epistemological, anthropological, ontological","Anthropological, sociological, commercial","Epistemological, sociological, ontological"],"correct":1,"explanation":"The listed approaches are epistemological, anthropological and ontological.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A10','{"id":"A10","stem":"A technology team checks whether its methods are permissible or prohibited in Islam. Which pair guides this check?","options":["Supply and demand","Profit and loss","Halal and haram","Tradition and popularity"],"correct":2,"explanation":"Halal and haram concern permissibility and prohibition in the Islamic ethical framework.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A11','{"id":"A11","stem":"Why did translating works from earlier civilizations support scientific growth?","options":["It removed the need for skilled scholars","It made existing knowledge available for further study","It proved that new research was unnecessary","It stopped cultural contact"],"correct":1,"explanation":"Translation gave scholars access to earlier learning that they could study and develop.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A12','{"id":"A12","stem":"Which activity best reflects the intellectual spirit of the Islamic Golden Age?","options":["Seeking knowledge across different scholarly traditions","Restricting learning to inherited stories","Rejecting every foreign book","Preventing discussion between scholars"],"correct":0,"explanation":"The source links intellectual growth to encouragement to seek knowledge widely.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A13','{"id":"A13","stem":"A display groups Hippocrates, Galen and Imhotep together. What is their shared association in this course?","options":["The invention of the internet","The translation of Arabic poetry only","Modern factory production","The history of medicine"],"correct":3,"explanation":"These three figures are associated with medicine in the course overview of early civilizations.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A14','{"id":"A14","stem":"Who best fits a study card headed \"translation of earlier medical learning\"?","options":["Al-Khwarizmi","Plato","Pythagoras","Hunayn ibn Ishaq"],"correct":3,"explanation":"Hunayn ibn Ishaq is the translator associated with the translation era in the source.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A15','{"id":"A15","stem":"A student writes \"Baitul Hikmah: House of Wisdom, Baghdad.\" Which part needs correction?","options":["The city only","Both the meaning and the city","The meaning only","Neither the meaning nor the city"],"correct":3,"explanation":"Baitul Hikmah means House of Wisdom and is associated with Baghdad.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A16','{"id":"A16","stem":"A historian studies ancient Mesopotamian clay tablets containing prescribed remedies. What do these show?","options":["Early recording of medical knowledge","The existence of modern vaccination campaigns","The use of digital medical files","The beginning of steam-powered factories"],"correct":0,"explanation":"The source identifies medication recorded on clay tablets as an early Mesopotamian medical achievement.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A17','{"id":"A17","stem":"Which pairing correctly links a scholar with a medical work?","options":["Ibn Sina - Al-Qanun fi al-Tibb","Hunayn ibn Ishaq - Al-Qanun fi al-Tibb","Pythagoras - Al-Qanun fi al-Tibb","Al-Khwarizmi - Al-Qanun fi al-Tibb"],"correct":0,"explanation":"Ibn Sina authored Al-Qanun fi al-Tibb, also known as The Canon of Medicine.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A18','{"id":"A18","stem":"Which statement describes an important role of scholars such as Al-Khwarizmi in numeration?","options":["Creating numbers with no earlier influences","Replacing all mathematics with astronomy","Explaining and spreading Hindu-Arabic calculation methods","Inventing the Roman numeral system"],"correct":2,"explanation":"Al-Khwarizmi wrote on Hindu-Arabic calculation; the contribution involved transmission and development.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A19','{"id":"A19","stem":"A revision card reads \"Greek mathematics and number theory.\" Which name best completes it?","options":["Imhotep","Galen","Pythagoras","Hunayn ibn Ishaq"],"correct":2,"explanation":"Pythagoras is the Greek mathematician linked with numbers in the course.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A20','{"id":"A20","stem":"Which activity best fits Baghdad as a centre of learning in the course?","options":["Developing the modern internet","Starting the steam-powered factory system","Collecting manuscripts and checking translations","Ending contact with Greek and Persian knowledge"],"correct":2,"explanation":"The Baghdad account emphasizes manuscripts, translation and Baitul Hikmah.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A21','{"id":"A21","stem":"A lesson links Damascus with practical advances. Which example fits?","options":["Online communication networks","Computer-controlled factories","Electronic medical records","Shipbuilding and agricultural techniques"],"correct":3,"explanation":"The source associates Damascus with shipbuilding, naval tools and agricultural techniques.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A22','{"id":"A22","stem":"A researcher removes an inconvenient result before publishing a report. Which principle is most directly violated?","options":["Speed of communication","Technical skill","Scientific honesty","Freedom to choose a research topic"],"correct":2,"explanation":"Scientific honesty requires truthful and accurate reporting, including inconvenient findings.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A23','{"id":"A23","stem":"In the Islamic framework taught here, beneficial scientific study can be understood as what?","options":["A substitute for every religious duty","An activity valuable only for income","An act of worship when pursued responsibly","A pursuit with no ethical obligations"],"correct":2,"explanation":"The course presents responsible scientific study as capable of being worship and service to Allah.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A24','{"id":"A24","stem":"A team says, \"Our invention works, so its harmful social effects do not matter.\" Which reply best reflects value-based science?","options":["Success must also be judged against ethics and social responsibility","Social effects belong outside every research decision","Any effective invention is automatically acceptable","Only the selling price matters"],"correct":0,"explanation":"Value-based science considers ethical responsibilities as well as technical results.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A25','{"id":"A25","stem":"A company uses a prohibited method to achieve a useful technological goal. How should this be assessed in the Islamic framework?","options":["A useful goal does not make an unethical method acceptable","Ethics applies only after the product is sold","The result alone determines whether the action is right","The method becomes acceptable if profits rise"],"correct":0,"explanation":"The source emphasizes that Shariah ethics constrain methods as well as goals.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A26','{"id":"A26","stem":"Which response shows a scientific characteristic identified in the course?","options":["Rely only on a person''s status","Use logical reasoning to examine the claim","Avoid asking for supporting evidence","Accept the claim because it is fashionable"],"correct":1,"explanation":"Logic is identified as a scientific characteristic.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A27','{"id":"A27","stem":"In the criticism attributed to Richard Dawkins in the course, what is the central concern?","options":["Using mathematics to describe nature","Accepting authority or faith in place of evidence","Allowing experiments to be repeated","Collecting too many observations"],"correct":1,"explanation":"This is the criticism attributed to Dawkins, rather than a statement that every religion rejects evidence.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A28','{"id":"A28","stem":"A student explains Tawhid as \"the oneness of God.\" How should this definition be marked?","options":["Correct","Incorrect: it means the authority of scientists","Incorrect: it means technological progress","Incorrect: it means separation of all knowledge"],"correct":0,"explanation":"Tawhid refers to the oneness of God.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A29','{"id":"A29","stem":"Which statement best fits the Roman Catholic position summarized in this course?","options":["Science and religion must always contradict","Scientific study always requires rejecting faith","Religion makes every experiment unacceptable","Science and religion can exist in harmony"],"correct":3,"explanation":"The course summary presents the possibility of harmony; it does not describe every historical episode.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('A30','{"id":"A30","stem":"A scientist publishes full results and considers how an invention affects users. Which two commitments are visible?","options":["Profit and speed only","Popularity and authority","Secrecy and unlimited freedom","Scientific honesty and social responsibility"],"correct":3,"explanation":"Accurate reporting shows honesty, while considering effects on users shows social responsibility.","set":"A","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B1','{"id":"B1","stem":"Which scholar-field pairing is accurate?","options":["Pythagoras - Arabic medical translation","Al-Khwarizmi - mathematics","Ibn Sina - steam engines","Al-Biruni - internet design"],"correct":1,"explanation":"Al-Khwarizmi made major mathematical contributions, including work on algebra.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B2','{"id":"B2","stem":"A laboratory repeats an observation to check a claim. What feature of science does this demonstrate?","options":["Following popularity","Checking claims against evidence","Choosing conclusions before collecting data","Protecting claims from criticism"],"correct":1,"explanation":"Observation and testing allow scientific claims to be checked.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B3','{"id":"B3","stem":"Which action most clearly shows a community meeting fardu kifayah through science?","options":["Ensuring enough people have essential medical expertise","Treating all occupations as private hobbies","Leaving every shared need unmet","Requiring every person to become a surgeon"],"correct":0,"explanation":"A collective obligation requires sufficient expertise within the community, rather than identical careers for all.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B4','{"id":"B4","stem":"A book translator compares a translated passage with its original. Which scholarly role does this illustrate?","options":["Preventing cultural exchange","Checking the accuracy of translations","Replacing scientific study with guessing","Limiting all books to one reader"],"correct":1,"explanation":"The source identifies authentication of translation material as a role of Baitul Hikmah.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B5','{"id":"B5","stem":"A report leaves out failed trials to make a device look reliable. What should the researcher do?","options":["Change the failed results into successes","Keep only the successful results","Report the failed trials accurately","Delete the original records"],"correct":2,"explanation":"Scientific honesty requires an accurate account of the evidence, including failures.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B6','{"id":"B6","stem":"Which earlier traditions contributed to the cultural background of Islamic scientific growth?","options":["Only twentieth-century digital traditions","Only one isolated local tradition","Only modern industrial traditions","Greek, Persian, Egyptian and Sumerian traditions"],"correct":3,"explanation":"The source presents growth through contact with several earlier intellectual traditions.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B7','{"id":"B7","stem":"Which statement most clearly confuses fardu kifayah with fardu ain?","options":["A community needs enough skilled engineers","Scientific expertise may benefit the public","Every Muslim must personally qualify as an engineer","Different people may serve different community needs"],"correct":2,"explanation":"Fardu kifayah is collective; it does not require every Muslim to enter the same profession.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B8','{"id":"B8","stem":"A study card names Hunayn ibn Ishaq. Which description belongs beside it?","options":["Pioneer of steam-powered manufacturing","Scholar associated with the translation movement","Author of The Canon of Medicine","Greek thinker associated with number theory"],"correct":1,"explanation":"Hunayn ibn Ishaq is associated with translation, while The Canon is by Ibn Sina.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
