('B10','{"id":"B10","stem":"Which pair correctly matches the roots used in the course?","options":["Scientia - craft; techne - knowledge","Scientia - wealth; techne - religion","Scientia - authority; techne - truth","Scientia - knowledge; techne - art or craft"],"correct":3,"explanation":"The Latin root concerns knowledge, while the Greek root concerns art or craft.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B11','{"id":"B11","stem":"Which question most directly reflects an epistemological approach to technology?","options":["How do we know that a technical claim is justified?","What is the cheapest shipping option?","Which advertisement has the brightest colours?","How many products were sold yesterday?"],"correct":0,"explanation":"An epistemological approach examines knowledge and its justification.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B12','{"id":"B12","stem":"A library brings together scholars from different religions and backgrounds. Which role does this best support?","options":["Keeping knowledge within a single family","Ending the need for translation","Preventing the training of specialists","Exchange of knowledge across communities"],"correct":3,"explanation":"The source highlights diverse translators and cultural exchange within the learning environment.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B13','{"id":"B13","stem":"A student labels a medical text \"Al-Qanun fi al-Tibb by Ibn Sina.\" What does the title identify?","options":["A manual of steam engines","A book of Roman military law","The Canon of Medicine","A guide to internet networks"],"correct":2,"explanation":"Al-Qanun fi al-Tibb is Ibn Sina''s Canon of Medicine.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B14','{"id":"B14","stem":"A researcher notices a pattern and proposes a possible explanation to investigate. What has the researcher formed?","options":["A sales forecast unrelated to evidence","A hypothesis","A rule that cannot be questioned","A guaranteed final truth"],"correct":1,"explanation":"A hypothesis is a proposed explanation that can guide investigation.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B15','{"id":"B15","stem":"Why can scientific freedom have limits in the Islamic framework?","options":["All research questions are prohibited","Only wealthy people may investigate","Scientific reasoning has no role","Researchers have ethical and social responsibilities"],"correct":3,"explanation":"The source links scientific freedom with responsibility rather than unrestricted action.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B16','{"id":"B16","stem":"Which research action is empirical?","options":["Measuring and recording water temperature","Claiming private inspiration","Describing kashf as personal insight","Accepting a claim solely through inward experience"],"correct":0,"explanation":"Empirical investigation uses observable or measurable evidence.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
