('B18','{"id":"B18","stem":"Which statement avoids a common misconception about studying science?","options":["Religious responsibility makes observation unnecessary","Science can serve both human welfare and religious responsibility","Scientific learning has no social value","Science is always separate from religion"],"correct":1,"explanation":"The source connects beneficial scientific learning with human benefit and religious responsibility.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B19','{"id":"B19","stem":"A researcher asks whether a conclusion follows from its supporting reasons. Which characteristic is being used?","options":["Logic","Popularity","Blind imitation","Status"],"correct":0,"explanation":"Logic concerns the relationship between reasons and conclusions.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B20','{"id":"B20","stem":"Which contribution fits Al-Biruni in the course outline?","options":["Writing The Canon of Medicine","Work in astronomy, mathematics and geographical measurement","Developing the modern internet","Inventing steam-powered factories"],"correct":1,"explanation":"The source associates Al-Biruni with mathematics, astronomy and geographical measurement.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
