('B22','{"id":"B22","stem":"Which summary best describes the link between Baghdad and Baitul Hikmah?","options":["A centre designed to stop scholarly exchange","A centre established for digital automation","A centre of manuscripts, translation and scholarship","A centre devoted only to ship construction"],"correct":2,"explanation":"The source links Baghdad and Baitul Hikmah with translation, manuscripts and learning.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B23','{"id":"B23","stem":"What does Tawhid contribute to the Islamic view of nature in this course?","options":["Belief that scientists have unlimited authority","Separation of science from every ethical duty","Recognition of the oneness of God","Worship of technological progress"],"correct":2,"explanation":"Tawhid expresses the oneness of God within the Islamic worldview.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B24','{"id":"B24","stem":"Which statement about number systems is most accurate?","options":["Roman numerals were invented by Al-Khwarizmi","Numerals developed without any contact between cultures","Islamic scholars helped transmit and develop Hindu-Arabic calculation","Algebra means abandoning all number systems"],"correct":2,"explanation":"The mathematical contribution includes transmission and development of calculation methods with Indian origins.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
('B25','{"id":"B25","stem":"A project is profitable but unjust to its users. Which judgment best fits Islamic technological principles?","options":["Profit does not make injustice acceptable","Profit automatically removes ethical concerns","Injustice is one of the guiding principles","User welfare is unrelated to technological decisions"],"correct":0,"explanation":"Injustice is excluded from the Islamic principles listed in the source.","set":"B","tag":"Revision challenge","follow":"Explain why the correct option fits, and why one other option does not."}'::jsonb,null),
